css:
.gallery {
  width: 100%;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 1em;
}

.slider {
  max-width: 1500px;
  margin: 0 auto;
  padding: 1em;
  width: 100%;
  height: 35em;
  position: relative;
  perspective: 1200px;
  display: flex;
  justify-content: center;
  align-items: center;
}

.wrapper {
  transform-style: preserve-3d;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  position: relative;
  width: 300px;
  height: 400px;
}

.slide {
  position: absolute;
  width: 150px;
  aspect-ratio: 3/4;
  transform-origin: bottom;
  animation: cardCycle 12s infinite;
}

.slide:nth-child(1) {
  animation-delay: 10s;
  background-color: #9b2948;
}

.slide:nth-child(2) {
  animation-delay: 8s;
  background-color: #ff7251;
}

.slide:nth-child(3) {
  animation-delay: 6s;
  background-color: #ffca7b;
}

.slide:nth-child(4) {
  animation-delay: 4s;
  background-color: #47894b;
}

.slide:nth-child(5) {
  animation-delay: 2s;
  background-color: #ffedbf;
}

.slide:nth-child(6) {
  animation-delay: 0s;
  background-color: #8d15ff;
}

@keyframes cardCycle {
  0% {
    transform: translateZ(0) rotateX(0);
    z-index: 2;
  }
  13.88% {
    transform: translateZ(600px) rotateX(90deg);
    z-index: 3;
  }
  16.66% {
    transform: translateZ(0px) rotateX(90deg);
    z-index: 1;
  }
  83.33% {
    transform: translateZ(0px) rotateX(0);
    z-index: 1;
  }
  97.22% {
    transform: translateZ(0) rotateX(0);
    z-index: 2;
  }
  100% {
    transform: translateZ(0) rotateX(0);
    z-index: 2;
  }
}
